CREATE TABLE merchants (id uuid PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), contact_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE printer_configurations (id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), name text NOT NULL, capabilities jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE pricing_rules (id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), currency char(3) NOT NULL, rule jsonb NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE print_jobs (id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), customer_id uuid REFERENCES customers(id), document_key text NOT NULL, page_count integer NOT NULL CHECK(page_count > 0), specifications jsonb NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor >= 0), currency char(3) NOT NULL, status text NOT NULL, collection_token text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE transactions (id uuid PRIMARY KEY, print_job_id uuid NOT NULL REFERENCES print_jobs(id), provider text NOT NULL, provider_reference text UNIQUE NOT NULL, amount_minor integer NOT NULL, currency char(3) NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
